/**
 * Catalog of every READ statement (SELECT) the Pi timer app can send, so a test
 * can run each one on SQLite and on PostgreSQL and compare the rows.
 *
 * GENERATED BY HAND from the source at the current HEAD + working tree
 * (branch claude/pi-timer-pg-port-3e4573, uncommitted edits included). It MUST be
 * updated whenever a query in one of these files changes:
 *   src/backend/server.ts, src/assets/*.ts, src/hooks/*.ts,
 *   src/common/**\/*.tsx, src/pages/**\/*.tsx, updater/update.ts
 *
 * `sqlite` / `pg` are the exact text the app sends on each engine (template
 * interpolations resolved for that branch; the two are identical when the code
 * does not go through sqlFor). `?` placeholders are turned into $n by the
 * backend. `params` mirrors what the code passes.
 *
 * Constants resolved to their literal values:
 *   PROGRESS_TIMETYPE (useJobs.ts)            = 1
 *   HANDOFF_KINDS (server.ts)                 = ["OFFER_TIMING_PN", "OFFER_TIMING"]  -> IN (?,?)
 *   CLOCKED_OUT_REASON (timingPage.tsx)       = "Clocked out (QuickBooks)"           -> Samples.reasonName
 *   INTERRUPTED_REASON (recoveryPage.tsx)     = "Interrupted (app closed)"           -> Samples.reasonName
 *   STATION_ID / os.hostname()                                                       -> Samples.station
 *   nowLocal()                                                                       -> Samples.now
 *   generated IN lists use the length of the Samples array passed (builderIds: 3 ids -> "?,?,?")
 *
 * Statements that only ever run on one engine are listed once with the text the
 * app sends there; the other spelling is identical here and is expected to fail
 * on the other engine (marked SQLITE-ONLY below):
 *   srv-msapikey, srv-segcrew-exists (server.ts skips both when engine === "pg")
 *   and the SQLite spelling of the sqlFor pairs (pragma_table_info, datetime(), ...).
 *
 * Not listed on purpose: SELECTs inside INSERT ... SELECT / UPDATE / DELETE
 * statements (writes), migrate()/ensureColumn()'s sqlite_master and
 * pragma_table_info probes, the CREATE VIEW body, and databaseSetup.tsx's
 * debug query.
 */
export interface Samples {
    builderId: number;
    buildId: number;
    segmentId: number;
    harnNumber: string;
    rev: number;
    phkid: number | null;
    timeTypeId: number;
    station: string;
    reasonName: string;
    now: string;
    msid: number;
    handoffKinds: string[];
    builderIds: number[];
    closedAt: string;
}

export interface CatalogEntry {
    id: string; // short unique slug
    source: string; // "src/hooks/useTimes.ts:fetchX" (file + function)
    sqlite: string; // EXACT text the app sends on SQLite
    pg: string; // EXACT text sent on pg (identical to sqlite when the code doesn't use sqlFor)
    params: (s: Samples) => unknown[]; // same arity/order as the app passes
    ordered: boolean; // true when the SQL has an ORDER BY that fully determines row order
}

// ---------------------------------------------------------------------------
// Fragments the app builds from constants / variants (copied from the source)
// ---------------------------------------------------------------------------

const PROGRESS_TIMETYPE = 1; // useJobs.ts

// useJobs.ts HARNESSES_OF_JOB / JOBS_SQL
const HARNESSES_OF_JOB = `
    SELECT PH.HARNPN FROM PROJHARN PH
     WHERE (V.PHKID IS NOT NULL AND PH.RID = V.REV AND PH.KITID = V.PHKID)
        OR (V.PHKID IS NULL AND V.PHID IS NOT NULL AND PH.PHID = V.PHID)`;

const JOBS_SQL = `
SELECT V.MSID, V.SEQ, V.HARNPN AS jobName, V.PHKITNAME, V.CUSTOMER, V.REVNUM, V.REV,
       V.PHKID, V.PHID, V.STATUS, V.TARGSTRTDATE, V.TARGENDDATE,
       COALESCE(V.HARNTOTAL, 0)    AS harnTotal,
       COALESCE(V.HARNREADYCNT, 0) AS harnReady,
       COALESCE(V.SHORTLINES, 0)   AS shortLines,
       COALESCE(V.FILLEDQTY, 0)    AS inStock,
       (SELECT COALESCE(SUM(PH.QTY * PH.ALTQTY), 0) FROM PROJHARN PH
         WHERE (V.PHKID IS NOT NULL AND PH.RID = V.REV AND PH.KITID = V.PHKID)
            OR (V.PHKID IS NULL AND V.PHID IS NOT NULL AND PH.PHID = V.PHID)) AS unitsTotal,
       (SELECT COUNT(*) FROM HARNBUILDTIMES_VIEW T
         WHERE T.REV = V.REV AND T.timeTypeId = ${PROGRESS_TIMETYPE}
           AND T.openSegments = 0 AND T.harnNumber IN (${HARNESSES_OF_JOB})) AS unitsBuilt,
       (SELECT COUNT(*) FROM HARNBUILDTIMES_VIEW T
         WHERE T.REV = V.REV AND T.timeTypeId = ${PROGRESS_TIMETYPE}
           AND T.openSegments > 0 AND T.harnNumber IN (${HARNESSES_OF_JOB})) AS unitsRunning
  FROM MSSCHED_VIEW V
 WHERE V.REV IS NOT NULL AND V.STATUS <> 'DONE'
 ORDER BY V.SEQ ASC`;

// useJobs.ts harnProgressSql(excludeSpread); the kit test is the sqlFor pair
function harnProgressSql(excludeSpread: boolean, pg: boolean): string {
    const spreadExclusion = excludeSpread
        ? "AND T.harnBuildTimeId NOT IN (SELECT harnBuildTimeId FROM HARNBUILDTIMES WHERE unitDecision='SPREAD')"
        : "";
    return `
SELECT PH.HARNPN AS partNum,
       (SELECT COUNT(*) FROM HARNBUILDTIMES_VIEW T
         WHERE T.harnNumber = PH.HARNPN AND T.REV = PH.RID
           AND T.timeTypeId = ${PROGRESS_TIMETYPE} AND T.openSegments = 0 ${spreadExclusion}) AS built,
       (SELECT COUNT(*) FROM HARNBUILDTIMES_VIEW T
         WHERE T.harnNumber = PH.HARNPN AND T.REV = PH.RID
           AND T.timeTypeId = ${PROGRESS_TIMETYPE} AND T.openSegments > 0) AS running
  FROM PROJHARN PH
 WHERE PH.RID = ? AND (${pg ? "?::integer IS NULL OR PH.KITID = ?::integer" : "? IS NULL OR PH.KITID = ?"})`;
}

// useTimes.ts SPREAD_EXCLUSION
const SPREAD_EXCLUSION =
    "AND harnBuildTimeId NOT IN (SELECT harnBuildTimeId FROM HARNBUILDTIMES WHERE unitDecision='SPREAD')";

// useTimes.ts countOnRev's sql(spread)
const countOnRevSql = (spread: boolean) =>
    `SELECT COUNT(*) AS n FROM HARNBUILDTIMES_VIEW WHERE harnNumber = ? AND timeTypeId = ? AND REV = ? AND openSegments = 0 ${spread ? SPREAD_EXCLUSION : ""}`;

// useSettings.ts usersByLastUse()
const usersByLastUseHead =
    "SELECT b.*, (SELECT MAX(s.startTime) FROM HARNBUILDSEGMENTS s WHERE s.builderId = b.Id" +
    " OR s.buildId IN (SELECT t.buildId FROM HARNBUILDTIMES t WHERE t.builderId = b.Id)" +
    " OR s.buildId IN (SELECT sb.buildId FROM SECONDARYBUILDERS sb WHERE sb.builderId = b.Id)) AS lastUsed";
const usersByLastUseSqlite =
    usersByLastUseHead + " FROM HARNBUILDERS b WHERE b.active != 0 ORDER BY lastUsed IS NULL, lastUsed DESC, b.Id";
const usersByLastUsePg =
    usersByLastUseHead + " FROM HARNBUILDERS b WHERE b.active != 0 ORDER BY lastUsed DESC NULLS LAST, b.Id";

// useBuildKit.ts fetchKit: the two spellings of the sqlFor pair
const KIT_SQLITE = `SELECT CASE WHEN LAG(PHK.PHKITNAME) OVER (ORDER BY BKL.BLDORD ASC, PH.INBUILD ASC) = PHK.PHKITNAME THEN '' ELSE PHK.PHKITNAME END AS 'Kit Name', PH.HARNPN, BKL.REV, (PH.QTY * PH.ALTQTY) AS 'Qty To Build', printf('%.2f',PH.SCHTIMEDAYS) AS 'Days To Complete PN', printf('%.2f',PH.SPLSETUPTIME * PH.QTY * PH.ALTQTY) AS 'Target Setup Time (Minutes)', printf('%.2f',PH.SPLBUILDTIME) AS 'Target Build Time (Minutes)', printf('%.2f',PH.BRDTIME) AS 'Target Braid Time (Minutes)' FROM BUILDKITLIST BKL LEFT JOIN PROJHARN PH ON PH.KITID = BKL.PHKID AND PH.RID = BKL.REV LEFT JOIN PERMHARNKITS PHK ON PHK.PHKID = BKL.PHKID WHERE BKL.REV=(?) AND ((?) IS NULL OR BKL.PHKID = (?)) ORDER BY BKL.BLDORD ASC, PH.INBUILD ASC;`;
const KIT_PG = `SELECT CASE WHEN LAG(PHK.PHKITNAME) OVER (ORDER BY BKL.BLDORD ASC, PH.INBUILD ASC) = PHK.PHKITNAME THEN '' ELSE PHK.PHKITNAME END AS "Kit Name", PH.HARNPN, BKL.REV, (PH.QTY * PH.ALTQTY) AS "Qty To Build", to_char(COALESCE(PH.SCHTIMEDAYS, 0), 'FM9999999990.00') AS "Days To Complete PN", to_char(COALESCE(PH.SPLSETUPTIME * PH.QTY * PH.ALTQTY, 0), 'FM9999999990.00') AS "Target Setup Time (Minutes)", to_char(COALESCE(PH.SPLBUILDTIME, 0), 'FM9999999990.00') AS "Target Build Time (Minutes)", to_char(COALESCE(PH.BRDTIME, 0), 'FM9999999990.00') AS "Target Braid Time (Minutes)" FROM BUILDKITLIST BKL LEFT JOIN PROJHARN PH ON PH.KITID = BKL.PHKID AND PH.RID = BKL.REV LEFT JOIN PERMHARNKITS PHK ON PHK.PHKID = BKL.PHKID WHERE BKL.REV=(?) AND ((?::integer) IS NULL OR BKL.PHKID = (?::integer)) ORDER BY BKL.BLDORD ASC, PH.INBUILD ASC;`;

// crewSlices.ts findOpenElsewhere(): the ownership test is the sqlFor pair
const openElsewhereSql = (stationTest: string) => `SELECT b.Id AS builderId, b.userName AS name, s.buildId AS buildId, s.stationId AS stationId,
                h.harnNumber AS harnNumber, CASE WHEN s.builderId = b.Id THEN 1 ELSE 0 END AS isPrimary
           FROM HARNBUILDERS b
           JOIN HARNBUILDSEGMENTS s
             ON COALESCE(s.endTime, '') = '' AND s.stationId IS NOT NULL AND s.buildId <> ?
            AND (${stationTest} OR s.stationId = 'RT-MCS phone')
            AND (s.builderId = b.Id
                 OR EXISTS (SELECT 1 FROM SECONDARYBUILDERS sb WHERE sb.buildId = s.buildId AND sb.builderId = b.Id))
           LEFT JOIN HARNBUILDS h ON h.buildId = s.buildId
          WHERE b.Id IN (?,?,?)
          ORDER BY s.segmentId DESC`;

// crewSlices.ts readReleaseAudit(): the time window is the sqlFor pair
const releaseAuditSql = (window: string) => `SELECT r.ACTION AS action, r.STATION AS station, r.VIA AS via, r.AT AS at,
                rb.userName AS byName, rw.userName AS whoName
           FROM MSTIMERRELEASE r
           LEFT JOIN HARNBUILDERS rb ON rb.Id = r.BYBUILDERID
           LEFT JOIN HARNBUILDERS rw ON rw.Id = r.BUILDERID
          WHERE r.BUILDID = ? AND r.ACTION = ?
            AND r.AT BETWEEN ${window}
          ORDER BY r.ID DESC LIMIT 1`;
const RELEASE_WINDOW_SQLITE = "datetime(?, '-10 seconds') AND datetime(?, '+10 seconds')";
const RELEASE_WINDOW_PG =
    "to_char(?::timestamp - interval '10 seconds', 'YYYY-MM-DD HH24:MI:SS')" +
    " AND to_char(?::timestamp + interval '10 seconds', 'YYYY-MM-DD HH24:MI:SS')";

// timingPage.tsx checkClock(): the join test is the sqlFor pair
const clockSql = (join: string) => `SELECT b.qbAutoPause, b.qbTimeUserId, s.onTheClock, p.lastPollAt,
                        (SELECT Id FROM HARNBUILDPAUSEREASONS WHERE reason_name = ? LIMIT 1) AS reasonId
                   FROM HARNBUILDERS b
              LEFT JOIN QBTIMESTATUS s ON ${join}
              LEFT JOIN QBTIMEPOLL   p ON p.id = 1
                  WHERE b.Id = ?`;

// server.ts /api/recovery/scan
const RECOVERY_SCAN_SQL = `SELECT s.segmentId, s.buildId, s.startTime, s.heartbeatAt, s.heartbeatState,
              COALESCE(s.accumSeconds, 0)  AS segmentAccumSeconds,
              s.numberOfBuilders,
              b.harnNumber, h.REV, h.builderId, h.timeTypeId,
              bl.userName AS builderName,
              (SELECT COALESCE(SUM(COALESCE(accumSeconds, 0)), 0)
                 FROM HARNBUILDSEGMENTS WHERE buildId = s.buildId) AS buildAccumSeconds,
              (SELECT MIN(startTime) FROM HARNBUILDSEGMENTS WHERE buildId = s.buildId) AS buildStartTime
         FROM HARNBUILDSEGMENTS s
         JOIN HARNBUILDS       b  ON b.buildId = s.buildId
         JOIN HARNBUILDTIMES   h  ON h.buildId = s.buildId AND h.timeTypeId <> 4
    LEFT JOIN HARNBUILDERS     bl ON bl.Id = h.builderId
        WHERE COALESCE(s.endTime, '') = ''
          AND (s.stationId = ? OR s.stationId IS NULL)
        ORDER BY s.segmentId DESC
        LIMIT 1`;

// server.ts /api/handoff/pending (HANDOFF_KINDS has 2 entries -> "?,?")
const HANDOFF_PENDING_SQL = `SELECT HandoffId, Kind, FromApp, FromStation, HarnPn, Rev, TimeTypeId, BatchUnits, Note,
              CreatedAt, ExpiresAt
         FROM RTCT_ShopHandoff
        WHERE ToApp = 'TIMING'
          AND Kind IN (?,?)
          AND SeenAt IS NULL
          AND Response IS NULL
          AND (ExpiresAt IS NULL OR ExpiresAt > ?)
        ORDER BY HandoffId DESC`;

// server.ts sweepStaleClaims (the sqlFor pair)
const SWEEP_SQLITE = `SELECT HandoffId FROM RTCT_ShopHandoff
        WHERE ToApp = 'TIMING' AND SeenAt IS NOT NULL AND Response IS NULL
          AND (ToStation IS NULL OR ToStation = ? COLLATE NOCASE)
          AND (ExpiresAt IS NULL OR ExpiresAt < ?)`;
const SWEEP_PG = `SELECT HandoffId FROM RTCT_ShopHandoff
        WHERE ToApp = 'TIMING' AND SeenAt IS NOT NULL AND Response IS NULL
          AND (ToStation IS NULL OR lower(ToStation) = lower(?::text))
          AND (ExpiresAt IS NULL OR ExpiresAt < ?)`;

// server.ts /api/build/discard statements
const DISCARD_PAUSES_SQL = `SELECT startTime, endTime, pauseReasonId FROM HARNBUILDTIMES
                 WHERE buildId = ? AND timeTypeId = 4 ORDER BY startTime`;
const DISCARD_SEGMENTS_SQL = `SELECT segmentId, builderId, numberOfBuilders, accumSeconds, startTime, endTime
                  FROM HARNBUILDSEGMENTS WHERE buildId = ? ORDER BY segmentId`;

// timingPage.tsx columnSupportsUnitDecision (the sqlFor pair)
const UNIT_DECISION_SQLITE = `SELECT COUNT(*) AS n FROM pragma_table_info('HARNBUILDTIMES') WHERE name = 'unitDecision'`;
const UNIT_DECISION_PG = `SELECT COUNT(*) AS n FROM information_schema.columns
                      WHERE table_schema = current_schema() AND table_name = 'harnbuildtimes' AND column_name = 'unitdecision'`;

/** An entry whose SQL is the same text on both engines. */
function same(
    id: string,
    source: string,
    sql: string,
    params: (s: Samples) => unknown[],
    ordered: boolean
): CatalogEntry {
    return { id, source, sqlite: sql, pg: sql, params, ordered };
}

